(function(root){const logic={
 create(){return {clock:0,appointments:{},interviews:{},requests:[],docs:[],ledgerChecked:false,tab:'field',npc:null}},
 ready(r){const missing=[];if(!r.docs.includes('contract'))missing.push('閱讀本案合約');if(!r.docs.includes('decision'))missing.push('調閱決策及授權紀錄');if(!r.docs.includes('ledger'))missing.push('調閱總帳與分部勾稽');if(!r.docs.includes('counter'))missing.push('取得企業反證');if(r.requiresCapacity&&!r.docs.includes('capacity'))missing.push('取得事前財務能力及資金資料');const witnesses=Object.entries(r.interviews).filter(([role,v])=>role!=='taxpayer'&&v.topics.some(t=>['decision','example','cross','capacity','counter'].includes(t)));if(witnesses.length<2)missing.push('訪談至少兩位不同來源的角色，並提出具體追問');if(!witnesses.some(([k])=>k==='finance'||k==='cpa'))missing.push('向財會人員或會計師核對財務／反證');if(!witnesses.some(([,v])=>v.topics.includes('cross')))missing.push('至少一次使用實際決策資料反問核對');if(!r.ledgerChecked)missing.push('完成帳務差額勾稽');return missing},
 advance(r){r.clock++;for(const request of r.requests){if(request.status==='pending'&&request.due<=r.clock){request.status='received';for(const d of request.docs)if(!r.docs.includes(d))r.docs.push(d)}}return r},
 request(r,docs,purpose,scope){if(scope!=='transaction')return {ok:false,error:'調閱須與本案課稅目的及必要範圍相關；請縮小範圍。'};if(!docs.length||purpose.trim().length<6)return {ok:false,error:'請選擇資料並具體說明要驗證的事實。'};r.requests.push({docs:[...new Set(docs)],purpose,scope,due:r.clock+1,status:'pending'});return {ok:true}},
 available(r,role){return r.appointments[role]!==undefined&&r.appointments[role]<=r.clock}
};if(typeof module!=='undefined'&&module.exports)module.exports=logic;else root.TPRPG=logic})(typeof window!=='undefined'?window:globalThis);
